const __pageData = JSON.parse('{"title":"DQL基本查询与条件查询","description":"第 5 章 DQL 部分的第一篇。先把 DQL 是什么（Data Query Language，关键字 select）和完整的七段式查询结构摆清楚，再拆开前两段——基本查询（查哪些字段，含多字段、通配符、别名、去重四种写法）与条件查询（where 怎么写，含八个比较运算符与三个逻辑运算符，between、in、like、is null 各有实测），每条 SQL 都在 emp 表 30 条数据上跑过并附真实输出","frontmatter":{"title":"DQL基本查询与条件查询","published":"2026-09-29T00:00:00.000Z","description":"第 5 章 DQL 部分的第一篇。先把 DQL 是什么（Data Query Language，关键字 select）和完整的七段式查询结构摆清楚，再拆开前两段——基本查询（查哪些字段，含多字段、通配符、别名、去重四种写法）与条件查询（where 怎么写，含八个比较运算符与三个逻辑运算符，between、in、like、is null 各有实测），每条 SQL 都在 emp 表 30 条数据上跑过并附真实输出","tags":["JavaWeb","MySQL","后端"],"image":"https://img.tsh520.cn/file/blog/post-covers/javaweb-46-dql-basic-query.webp","order":46,"date":"2026-09-29T00:00:00.000Z","cover":false,"hidden":true},"headers":[],"relativePath":"posts/学习文档/JavaWeb学习笔记/46-DQL基本查询与条件查询.md","filePath":"posts/学习文档/JavaWeb学习笔记/46-DQL基本查询与条件查询.md"}');
